tool_calls.arguments:
{"command":"# 3. Patch the deployment to add a volume definition and a volume mount.
# This allows the application to write to /app/data while the root filesystem remains read-only.
kubectl patch deployment app --type='json' -p='[
  {
    "op": "add",
    "path": "/spec/template/spec/volumes/0",
    "value": {
      "name": "data-volume",
      "emptyDir": {}
    }
  },
  {
    "op": "add",
    "path": "/spec/template/spec/containers/0/volumeMounts/0",
    "value": {
      "name": "data-volume",
      "mountPath": "/app/data"
    }
  }
]'
"}

{"command":"# 3. Use a JSON merge patch to add a volume and mount it to /var/log.
# This maintains readOnlyRootFilesystem: true while providing a writable location.
kubectl patch deployment app --type merge -p '
{
  "spec": {
    "template": {
      "spec": {
        "volumes": [
          {
            "name": "write-volume",
            "emptyDir": {}
          }
        ]
      }
    }
  }
}'
"}

